def main():
 out=ROOT/'outputs';d=pd.read_csv(out/'all_main.csv');ch=pd.read_csv(out/'challenge_normal.csv');tail=pd.read_csv(out/'tail_retention.csv');paired=pd.read_csv(out/'all_main_paired.csv');sens=pd.read_csv(out/'sensitivity_paired.csv');pv=pd.read_csv(out/'prim_validation.csv');pe=pd.read_csv(out/'prim_external_validation.csv');ec=pd.read_csv(out/'common_domain_economics.csv');inv=json.loads((out/'experiment_inventory.json').read_text())
 def count(p,c='funded',h=str(CORE),data=d):return int(data[(data.policy==p)&(data.horizon==h)][c].sum())
 def share(p,c='funded',h=str(CORE),data=d):
  z=data[(data.policy==p)&(data.horizon==h)];value=(Decimal(int(z[c].sum()))*100/Decimal(len(z))).quantize(Decimal('0.1'),rounding=ROUND_HALF_UP);return f'{value}%'
 def pair(p,c='funded'):
  return paired[(paired.policy==p)&(paired.comparator=='bps_100')&(paired.horizon==str(CORE))&(paired.outcome==c)].iloc[0]
 def transfer(outcome,split):
  if split=='challenge':return pe[(pe.phase==split)&(pe.policy=='bps_100')&(pe.horizon==str(CORE))&(pe.outcome==outcome)&(pe.box=='1')].iloc[0]
  return pv[(pv.split==split)&(pv.policy=='bps_100')&(pv.horizon==str(CORE))&(pv.outcome==outcome)&(pv.box=='1')].iloc[0]
 doc=Document();sec=doc.sections[0];sec.page_width=Inches(8.5);sec.page_height=Inches(11);sec.top_margin=Inches(.75);sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.85)
 for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Caption']:
  st=doc.styles[name];st.font.name='Cambria';st.font.color.rgb=RGBColor(0,0,0)
 normal=doc.styles['Normal'];normal.font.size=Pt(11);normal.paragraph_format.space_after=Pt(7);normal.paragraph_format.line_spacing=1.06
 doc.styles['Title'].font.size=Pt(24);doc.styles['Subtitle'].font.size=Pt(12)
 # Remove the template's decorative title border.
 for st in [doc.styles['Title'],doc.styles['Subtitle']]:
  pr=st.element.find(qn('w:pPr'))
  if pr is not None:
   for border in list(pr.findall(qn('w:pBdr'))):pr.remove(border)
 for name,size in [('Heading 1',15),('Heading 2',12)]:
  doc.styles[name].font.size=Pt(size);doc.styles[name].paragraph_format.space_before=Pt(14);doc.styles[name].paragraph_format.space_after=Pt(6)
 doc.styles['Caption'].font.size=Pt(9);doc.styles['Caption'].font.italic=False;doc.styles['Caption'].font.bold=False
 foot=sec.footer.paragraphs[0];foot.alignment=WD_ALIGN_PARAGRAPH.CENTER
 fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');foot._p.append(fld)
 doc.core_properties.title='Strategy financing under deep uncertainty';doc.core_properties.subject='RDM results and robustness checks';doc.core_properties.author='Murray A. Rudd'
 def para(s,style=None):return doc.add_paragraph(s,style)
 def head(s):doc.add_heading(s,level=1)
 def table(headers,rows,widths=None):
  t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
  widths=widths or [6.8/len(headers)]*len(headers)
  for col,width in zip(t.columns,widths):col.width=Inches(width)
  for j,h in enumerate(headers):t.rows[0].cells[j].text=h
  for row in rows:
   c=t.add_row().cells
   for j,v in enumerate(row):c[j].text=str(v)
  for i,row in enumerate(t.rows):
   for j,c in enumerate(row.cells):
    c.width=Inches(widths[j]);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    pr=c._tc.get_or_add_tcPr();borders=OxmlElement('w:tcBorders')
    for edge in ['top','left','bottom','right']:
     el=OxmlElement('w:'+edge);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D9D9D9');borders.append(el)
    pr.append(borders);shd=OxmlElement('w:shd');shd.set(qn('w:fill'),'404040' if i==0 else ('F4F4F4' if i%2==0 else 'FFFFFF'));pr.append(shd)
    margins=OxmlElement('w:tcMar')
    for side in ['top','left','bottom','right']:
     x=OxmlElement('w:'+side);x.set(qn('w:w'),'80');x.set(qn('w:type'),'dxa');margins.append(x)
    pr.append(margins)
    for p in c.paragraphs:
     p.paragraph_format.space_after=Pt(2);p.paragraph_format.space_before=Pt(2);p.paragraph_format.line_spacing=1.0
     p.paragraph_format.keep_with_next=i<len(t.rows)-1
     p.alignment=WD_ALIGN_PARAGRAPH.LEFT if j==0 or (len(headers)==2 and widths[j]>4) else WD_ALIGN_PARAGRAPH.CENTER
     for r in p.runs:r.font.size=Pt(9.5);r.bold=i==0;r.font.color.rgb=RGBColor(255,255,255) if i==0 else RGBColor(0,0,0)
   trpr=row._tr.get_or_add_trPr();cant=OxmlElement('w:cantSplit');trpr.append(cant)
  repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
  para('')
  return t
 def figure(name,caption):
  p=para('');p.paragraph_format.keep_with_next=True
  shape=p.add_run().add_picture(str(ROOT/'figures'/(name+'.png')),width=Inches(6.65));shape._inline.docPr.set('descr',caption)
  para(caption,'Caption')
 para('Strategy financing under deep uncertainty','Title')
 para('RDM results through 2033 with financing closure challenges','Subtitle')
 para(f'Research analysis for Murray A. Rudd  •  October 11 2026  •  Release {EXTENSION_VERSION}')
 para('Extending the simulation horizon makes the financing problem materially different. Policies that complete the near-term cash schedule can later breach reserves or fail at a principal repayment date. Protecting cash receipts alone changes few outcomes. Raising cash ahead of known commitments produces a larger improvement, although it does not preserve Bitcoin per share or withstand every combined stress.')
 para(f'The primary experiment compares ten policies across 2,000 matched futures. For the full STRC program with the Bitcoin-per-share issuance screen, the share meeting both payments and reserve requirements falls from {share("bps_100",h="2027-09-30")} at the original checkpoint to {share("bps_100")} in June 2031 and {share("bps_100",h=str(LONG))} in June 2033. The advance-funding rule with bounded Bitcoin sale authority raises those longer-horizon shares to {share("anticipatory_sale")} and {share("anticipatory_sale",h=str(LONG))}. These are frequencies within the designed experiments, not estimated probabilities.')
 table(['Policy','2031 funded','2031 value','2033 funded','2033 value'],[[LABELS[p],share(p),share(p,'nominal_value'),share(p,h=str(LONG)),share(p,'nominal_value',str(LONG))] for p in SELECT],[2.35,1.1,1.1,1.1,1.1])
 para('Funded requires every conditional payment and reserve compliance at every corporate event. Value additionally requires preservation of the opening common-share quote. The same future appears under every policy; the paired results below identify gains and losses that marginal shares can conceal. The findings support an RDM paper centered on repayment timing, financing access and the separation of corporate funding from shareholder objectives.')
 head('Decision framing and experimental design')
 para('The decision question is which financing and cash-allocation rules can maintain specified outcomes across prolonged market stress and the existing repayment cycle. RDM provides the organizing method: compare policies across uncertain futures, identify their vulnerabilities, revise rules using those findings, and test the revisions on reserved futures [9]. Policy-oriented scenario discovery follows Bryant and Lempert [12], using PRIM as implemented in EMA Workbench [10,13].')
 para('The analysis retains the June 30, 2026 corporate opening and the August 3, 2026 information cutoff. It evaluates September 2027 and June 2029 checkpoints, a June 2031 core endpoint, and a June 2033 sensitivity endpoint. Each long endpoint also receives a separate 12-month continuation with both issuance channels closed, with and without an additional market shock. This preserves comparability with the original model while exposing later obligations; it does not refresh the opening to October 2026.')
 para('The retained opening holds 846,000 Bitcoin, approximately $2.448 billion of unrestricted cash and Treasuries, and 371.603 million basic common shares. Debt principal totals $6.754 billion; opening STRC stated principal is $10.489 billion. Other preferred classes and their distributions remain in the ledger. Bitcoin begins at $58,714 and the conditional common quote at $86.93. These starting values come from the frozen source configuration.')
 table(['Element','Specification'],[
  ['Uncertainties','Bitcoin paths; valuation; financing capacity and closures; preferred rates and prices; operating cash flow; EUR exchange rates; puts; authorization renewal'],
  ['Levers','Common issuance screen; STRC program scale; cash coverage; preferred principal cap; advance funding; bounded general-purpose Bitcoin sales'],
  ['Relationships','Dated balance sheet and cash ledger; T+1 issuance; record-date entitlements; conditional common valuation; state-dependent financing rules'],
  ['Measures','Payments; reserves; common value and 5% annual return; Bitcoin per share; daily drawdown; financing, dilution, sales and continuing preferred service']],[1.1,5.65])
 para('A Latin hypercube supplies 2,000 exploratory futures. Of these, 1,500 use stylized drawdowns and recoveries, including repeated shocks; 500 resample 180-day Bitcoin return blocks from 2014–2019. Half of the design links financing and valuation stress to Bitcoin drawdowns; the other half varies access independently. The design crosses full holder puts with no puts and fixed authorizations with dated renewals. No weights imply beliefs about which futures will occur.')
 table(['Uncertainty','Main design range'],[
  ['Underlying Bitcoin growth trend','−25% to +45% annually'],['Stylized shock depth and recovery','15%–80%; 0.4–3.0 years'],['Financing closure duration','0–36 months'],['Capacity multiplier before linked stress','0.05–1.25'],['Baseline valuation factor by year five','0.35–2.50 times the opening multiplier'],['STRC base rate and stress increment','10%–16%; additional 0–6 percentage points'],['STRC discount from stated amount','$0–$15 per share, before the issuance gate'],['Annual operating cash flow','−$300 million to +$100 million'],['EUR value at year five','0.75–1.35 times the opening USD value']],[3.5,3.25])
 para('Linked stress can further depress valuation and capacity. Each path has one explicit financing-closure window; subsequent drawdowns can reduce capacity without automatically creating another closure. Realized trajectory summaries can fall outside the underlying growth-trend range because historical blocks and drawdown timing also affect a checkpoint price. The block samples center cumulative noise over a common fixed path length. The reserved challenge uses 512 new futures: 256 with 2020–2025 return blocks and 256 with a different, prolonged-bottom recovery generator. Another 26 cases replay complete historical Bitcoin price shapes. Those 26 overlap the source pools and combine historical Bitcoin with conditional financing inputs, so they are descriptive checks, not independent historical validation of Strategy.')
 head('Policies and information available to managers')
 para('The six reference policies cross the original net-backing common issuance screen or the Bitcoin-per-share screen with zero, half or full new STRC programs. These screens govern discretionary growth issuance; the source model separately permits common issuance for funding needs. The two initial additions protect 12 months of projected cash uses, with or without a cap on new STRC stated principal at 50% of its opening amount. A cap on principal does not cap variable future distributions.')
 table(['Policy group','New STRC program','Cash rule','New STRC cap'],[
  ['Reference 0 50 100','0% 50% 100%','Original','None'],['BPS 0 50 100','0% 50% 100%','Original','None'],['Cash protection','100%','Protect 12 months','None'],['Cash and STRC cap','100%','Protect 12 months','50%'],['Advance cash funding','100%','Protect and fund 12 months','50%'],['Advance funding and sales','100%','Protect and fund 12 months plus sales','50%']],[2.0,1.35,2.35,1.05])
 para('Coverage includes known debt dates, preferred service valued at current rates and exchange rates, and operating cash uses. The rule counts designated reserves once. It protects against the earliest possible future holder put until that date passes, rather than using advance knowledge of eventual exercise. Current capacity, authorization and quotes constrain each placement. The rule cannot observe a future price, closure duration or future rate realization.')
 para('The completed discovery experiment motivated two revisions. Advance cash funding raises common capital before near-term cash coverage becomes deficient, accounting for pending proceeds. The second revision also authorizes cumulative general-purpose Bitcoin sales up to $6.754 billion gross, equal to opening debt principal. That is a bounded capital-allocation permission; it is not new collateral, a source of cash before a sale, or a claim that such permission guarantees reserve compliance. Both revisions were locked before the reserved challenge outcomes were generated.')
 head('Extended cash schedules and model boundaries')
 figure('06_principal_calendar','Figure 1. Contractual cash principal under the full-put and no-put branches. The vertical dotted line marks the original September 2027 endpoint. The small secured-loan approximation is retained from the source model.')
 para('The extension completes the existing note coupons and both retirement branches, including the large 2028 repayment concentrations and maturities through June 2032 [1,7]. Each debt claim retires once; coupons stop at retirement. The partial-put sensitivity divides each note into put and maturity portions so that the ledger preserves principal and accruals exactly. No automatic conversion or refinancing replaces the cash obligation.')
 para('Preferred schedules extend beyond each endpoint to support continuation tests and the coverage rule. STRF, STRE, STRK and STRD retain their stated rates, and every preferred cash payment remains conditional on declaration [3–6]. STRC uses semimonthly entitlement periods and monthly rate reference periods, preserves the opening credits, and limits downward rate changes to 25 basis points per month [2]. The rate scenario uses a fixed 3% SOFR floor and reacts to stress observed at least 20 days earlier. Calendar adjustments distinguish Federal Reserve, equity-market and euro payment dates [4,8]. Recurring calendars do not predict exceptional future closures.')
 para('Common valuation retains the original continuation benchmark: a zero-carry lognormal residual with 65% volatility and a three-year valuation horizon. This valuation horizon is separate from the cash simulation horizon. The benchmark supplies a conditional quote, not an independently estimated market price. The face-value sensitivity preserves the same opening quote before applying a different valuation relationship. A one-cent common execution floor prevents effectively unbounded placements as the modeled quote approaches zero; tests at $0.000001 and $1 examine that numerical and economic boundary. None of these floors is asserted to be an exchange rule.')
 head('What the longer horizon changes')
 figure('01_horizon_performance','Figure 2. Matched policy performance across four checkpoints. Each percentage uses all 2,000 designed futures. Nominal value includes the payment and reserve conditions; it is not a return statistic computed only for survivors.')
 para(f'All eight initial policies complete every payment through September 2027, although eight futures already breach the reserve floor. By June 2031, BPS 100 completes payments in {count("bps_100","payments")} cases and meets the stricter funded condition in {count("bps_100")} cases. The difference matters: 316 cases complete payments but breach the reserve requirement, while 310 stop at an unsupported payment. For those payment stops, 79 occur on March 1, 2028, 77 on March 1, 2030, 55 on September 15, 2028, and 38 on June 1, 2028. Repayment timing is therefore central to the vulnerability. All 310 stops include an asset-use permission gap; 165 also include a cash gap, while 145 have enough cash after proposed funding transactions but fail the specified use restriction. These are policy-contingent settlement failures, not a count of firms without assets to pay.')
 para(f'The protected-cash rule raises the five-year funded count from {count("bps_100")} to {count("liquidity_12")}, a gain of only three cases. Adding the preferred principal cap leaves the count at {count("liquidity_cap")}. This is evidence against treating a cash-retention instruction as sufficient adaptation. It can preserve available receipts, but it does not ensure that enough cash is raised before access deteriorates.')
 para(f'Bitcoin-per-share preservation is particularly demanding. BPS 100 meets that combined target in {count("bps_100","bitcoin_per_share")} five-year cases and {count("bps_100","bitcoin_per_share",str(LONG))} seven-year case. The advance-funding-and-sales rule meets it in {count("anticipatory_sale","bitcoin_per_share")} and {count("anticipatory_sale","bitcoin_per_share",str(LONG))} cases. A screen that protects Bitcoin per share on discretionary issuance does not protect that ratio against distributions, principal cash needs, funding dilution or subsequent sales.')
 f=pd.DataFrame(json.loads((ROOT/'inputs/futures_main.json').read_text()))
 strata=d.merge(f[['future_id','authorization_renewal']],on='future_id',validate='many_to_one')
 fixed=strata[~strata.authorization_renewal];renewed=strata[strata.authorization_renewal]
 table(['Policy','2031 fixed','2031 renewal','2033 fixed','2033 renewal'],[[LABELS[p],f'{count(p,data=fixed)}/1000',f'{count(p,data=renewed)}/1000',f'{count(p,h=str(LONG),data=fixed)}/1000',f'{count(p,h=str(LONG),data=renewed)}/1000'] for p in SELECT],[2.35,1.1,1.1,1.1,1.1])
 para('Funded counts by authorization branch. Fixed authority retains the original cumulative ceiling; renewal adds explicit dated authorizations. Each branch contains 1,000 different futures, with policies matched within each branch. Between-branch differences also reflect their other sampled conditions and do not isolate the causal effect of authorization. The revised policy advantage remains visible in the fixed-authority branch.')
 para('The preferred rule also depends on the evaluation date. At the September 2027 checkpoint, the combined revision preserves nominal common value in 994 cases, compared with 1,044 for BPS 100. At June 2031, the counts are 972 and 785. Holding cash and issuing earlier can impose an initial shareholder cost while improving resilience across later repayment dates.')
 head('Adaptation and the cost of robustness')
 figure('02_paired_policy_changes','Figure 3. Five-year gains and losses relative to BPS 100 in exactly matched futures. Gains and losses refer to each stated target, rather than to changes in the average return.')
 a=pair('anticipatory_12');b=pair('anticipatory_sale');v=pair('anticipatory_sale','nominal_value')
 para(f'Advance cash funding adds {int(a.gains)} funded successes and loses {int(a.losses)} relative to BPS 100. Adding bounded general-purpose sales produces {int(b.gains)} gains and {int(b.losses)} losses. For nominal common value, the combined revision produces {int(v.gains)} gains and {int(v.losses)} losses. These paired results identify the tradeoff directly; the policies do not become equivalent merely because their marginal percentages are similar.')
 diagnostic=pd.read_csv(out/'diagnostic_sales.csv')
 components=pd.concat([d[d.policy.isin(['liquidity_cap','anticipatory_12','anticipatory_sale'])],diagnostic],ignore_index=True)
 table(['Advance funding','General sales authority','Payments','Funded','Nominal value'],[[a,b,count(p,'payments',data=components),count(p,data=components),count(p,'nominal_value',data=components)] for p,a,b in [('liquidity_cap','No','None'),('anticipatory_12','Yes','None'),('sales_only','No','$6.754bn'),('anticipatory_sale','Yes','$6.754bn')]],[1.35,1.65,1.25,1.25,1.25])
 para('Post-discovery component comparison on all 2,000 main futures, at June 2031. Every row retains the same 12-month cash protection and 50% new-STRC cap. The sales-only diagnostic switches off advance funding while retaining the combined policy’s sale permission. This comparison was added for attribution after the primary challenge. It generated the interpretation tested on a separate fresh batch below.')
 cp=pd.read_csv(out/'component_diagnostic_paired.csv')
 r=cp[(cp.policy=='anticipatory_sale')&(cp.comparator=='sales_only')&(cp.horizon==str(CORE))&(cp.outcome=='funded')].iloc[0]
 r0=cp[(cp.policy=='anticipatory_12')&(cp.comparator=='liquidity_cap')&(cp.horizon==str(CORE))&(cp.outcome=='funded')].iloc[0]
 para(f'With sale permission already available, adding advance funding gains {int(r.gains)} funded cases and loses {int(r.losses)}. Without sale permission, it gains {int(r0.gains)} and loses {int(r0.losses)}. These component effects need not add across the two policy settings. The combined policy’s full improvement should not be attributed to advance funding alone.')
 e=ec[ec.horizon==str(CORE)].set_index('policy');n=int(e.loc['bps_100','common_defined_futures'])
 para(f'Dilution, preferred service and return comparisons below use the same {n:,} futures in which all ten policies complete the path and have a defined common valuation. This deliberately restricted domain cannot describe overall robustness; the full-design failure counts remain the primary comparison. The accompanying files report conditional return regret on this common domain and keep its denominator explicit.')
 table(['Policy','Share growth','New STRC gross','Annual preferred service','Common return'],[[LABELS[p],f'{100*e.loc[p,"common_share_growth_median"]:.0f}%',f'${e.loc[p,"strc_gross_usd_median"]/1e9:.2f}bn',f'${e.loc[p,"annual_preferred_runrate_usd_median"]/1e9:.2f}bn',f'{100*e.loc[p,"common_return_median"]:.0f}%'] for p in SELECT],[2.35,1.0,1.1,1.25,1.05])
 para('Values are medians on the common completed and mapped domain. Preferred service includes all outstanding preferred classes at the contemporaneous rate and exchange rate. It measures continuing cash burden, not a terminal principal writeoff. Undefined or stopped common returns are neither deleted from overall target counts nor assigned an invented value of zero.')
 para(f'Median maximum daily common-share drawdown on this same completed and mapped domain is {-100*e.loc["bps_100","daily_common_drawdown_median"]:.1f}% for BPS 100 and {-100*e.loc["anticipatory_sale","daily_common_drawdown_median"]:.1f}% for the combined revision. Meeting an endpoint target can therefore coexist with substantial interim losses.')
 figure('07_cash_timing_witness','Figure 4. Main future 1674 isolates cash timing during an independently specified financing closure. The cash-protection policy stops at the March 2028 payment; the advance-funding policy has raised cash before access closes. The stop marker records cash after permitted funding trades and before the blocked payment. This selected case explains a mechanism and does not estimate its frequency.')
 para('In this illustrative future, financing closes before the March 2028 principal payment while the underlying Bitcoin trend remains positive. The cash-protection policy records no immediate cash gap at its stop, but an asset-use permission gap of about $125 million blocks settlement. Advance funding uses the same sale permission and preferred cap; it changes when common proceeds arrive. The example makes the dependence on the specified funding hierarchy explicit.')
 para('The component comparison identifies different roles for the two levers. Sale permission alone raises five-year payment completion from 1,690 to 1,944 cases, while funded success rises only from 1,374 to 1,418. With sale permission already available, advance funding adds only eight net payment completions but 324 net funded successes. Asset-use flexibility primarily prevents settlement stops; advance funding primarily preserves the reserve condition. This distinction remains within the model’s stated cash and allocation assumptions.')
 head('Fresh validation of the component effects')
 fresh=pd.read_csv(out/'fresh_component_validation.csv');effects=pd.read_csv(out/'fresh_component_effects.csv')
 para('A new 512-future batch tests that interpretation after freezing the code, inputs, four policy combinations, endpoints and paired comparisons. Its 256 historical-block futures draw from 2020–2025, while 256 use the plateau-recovery generator. These are fresh random draws from the reserved challenge design. They do not introduce a new historical data pool or independently validate the corporate model. The primary comparison is payment completion versus funded success at June 2031; the seven-year endpoint and shareholder measures are secondary.')
 table(['Advance funding','General sales authority','Payments','Funded','Nominal value'],[[a,b,count(p,'payments',data=fresh),count(p,data=fresh),count(p,'nominal_value',data=fresh)] for p,a,b in [('liquidity_cap','No','None'),('anticipatory_12','Yes','None'),('sales_only','No','$6.754bn'),('anticipatory_sale','Yes','$6.754bn')]],[1.35,1.65,1.25,1.25,1.25])
 para('Five-year counts use all 512 fresh futures. Sale authority alone adds 78 payment completions and eight funded successes, with no losses on either measure. With sale authority already available, advance funding gains 102 funded cases and loses two, a net gain of 100; it gains seven payment completions and loses one. Without sale authority, advance funding adds 97 funded successes net and 47 payment completions. The distinction between payment flexibility and reserve protection therefore transfers to this fresh batch under both policy settings.')
 para(f'At June 2033, the combined rule meets the funded target in {count("anticipatory_sale",h=str(LONG),data=fresh)} of 512 futures, compared with {count("liquidity_cap",h=str(LONG),data=fresh)} under cash protection and the STRC cap alone. It preserves nominal common value in {count("anticipatory_sale","nominal_value",str(LONG),data=fresh)} cases and Bitcoin per share in none. No policy definition or success threshold was changed in response to the fresh results.')
 head('Vulnerability regions and their transfer')
 para('PRIM fits separately for each initial policy and failure target on 1,500 training futures; 500 futures remain an internal design holdout. The search uses 5% peeling and pasting, 5% minimum mass, at most three selected boxes, and no more than four restricted dimensions per box. It seeks 90% density and favors coverage among qualifying boxes. If no selected box reaches that density, the report retains and labels the weaker region. The exact rules and full peeling trajectories remain in the package.')
 para('For five-year BPS 100 nominal-value failure, the first box combines realized Bitcoin growth of at most about 8.4% annually, a Bitcoin minimum below about 92.4% of its opening value, and a terminal continuation-value multiplier below about 2.23. These are explanatory conditions on whole simulated futures. They are not observable forecasting thresholds that management can use at the opening date.')
 para('The first funding-failure box combines full holder puts, some financing closure, average realized capacity no greater than about 0.34 of the event-capacity scale, and a terminal multiplier below about 2.26. Its precision is lower. In particular, the selected four-dimension funding boxes do not reach the desired 90% density. They identify concentrations of vulnerability and leave substantial overlap between success and failure.')
 table(['Target and set','Inside cases','Failure density','Failure coverage'],[[('Funding' if o=='funded' else 'Value')+'  '+s.replace('train','training').replace('challenge','reserved challenge'),int(transfer(o,s).inside),f'{100*transfer(o,s).density:.1f}%',f'{100*transfer(o,s).coverage:.1f}%'] for o in ['funded','nominal_value'] for s in ['train','holdout','challenge']],[2.8,1.1,1.4,1.45])
 figure('03_prim_transfer','Figure 5. Transfer of the frozen first PRIM box for BPS 100. Density is the fraction of cases inside a region that fail; coverage is the fraction of all failures captured. The dotted line marks the 90% density target.')
 para('A depth-three CART diagnostic gives internal-holdout balanced accuracy of 0.743 for funded failure and 0.845 for nominal-value failure. It reinforces the roles of capacity, closure duration and the put branch for funding, and Bitcoin growth and valuation for common value. These diagnostics do not identify causal effects or calibrated probabilities. Nearly universal Bitcoin-per-share failure supplies too little outcome variation for useful scenario discovery; a one-class holdout is not treated as evidence of perfect prediction.')
 head('Reserved futures and financing closure')
 table(['Policy','Challenge funded 2031','Challenge value 2031','Challenge funded 2033'],[[LABELS[p],f'{count(p,data=ch)}/512',f'{count(p,"nominal_value",data=ch)}/512',f'{count(p,h=str(LONG),data=ch)}/512'] for p in SELECT],[2.65,1.4,1.4,1.3])
 para('The reserved set changes the source period for historical blocks and the shape of stylized recoveries. The revised policies and primary PRIM rules remain fixed during that test. This is a stronger transfer check than the random internal holdout, but it remains a challenge within an analyst-defined model and uncertainty set. It does not validate the model against a future realized corporate outcome.')
 figure('04_financing_closure','Figure 6. One-year funded retention conditional on already meeting the funded target at the endpoint. Relative to the same unshocked future, the combined stress applies a 40% Bitcoin markdown and 25% valuation-multiplier markdown over one year, and adds four percentage points to the STRC rate after the specified lag. Denominators differ by policy and endpoint.')
 table(['Policy','2031 endpoint','2032 closure','2032 closure and stress'],[[LABELS[p],int(tail[(tail.policy==p)&(tail.variant=='core_closure')&(tail.criterion=='funded')].iloc[0].endpoint_successes),int(tail[(tail.policy==p)&(tail.variant=='core_closure')&(tail.criterion=='funded')].iloc[0].tail_successes),int(tail[(tail.policy==p)&(tail.variant=='core_stress_closure')&(tail.criterion=='funded')].iloc[0].tail_successes)] for p in SELECT],[2.85,1.25,1.25,1.4])
 para('Counts in this table retain the full 2,000-future denominator. The chart instead asks how many endpoint funded successes survive the next year. Reporting both prevents an apparently high conditional retention rate from hiding a small successful starting set. Neither continuation test establishes indefinite solvency; preferred distributions continue after the final observation date.')
 para('Of the combined revision’s 1,742 funded successes in June 2031, 1,695 retain that status after a year with both issuance channels closed, and 1,590 after closure plus the additional stress. Conditional retention is therefore 97.3% and 91.3%. Its larger successful starting set remains the principal advantage: BPS 100 retains 1,331 and 1,261 funded cases under the same tests. Among endpoint survivors, the combined revision does not improve every retention percentage.')
 head('Structural sensitivities and severe combined stress')
 figure('05_structural_sensitivities','Figure 7. Paired change in the five-year funded share on the same 256 main-design futures. Face valuation preserves the opening common quote. Market-value capacity limits each issuance channel to 2% of contemporaneous modeled common market value at an event.')
 para('The sensitivity experiment also varies cash coverage to six or 18 months and the cap on new STRC stated principal to 25% or 100% of opening principal. These comparisons test policy design, while partial puts, valuation and market-value capacity test structural assumptions. The package reports gains and losses for each comparison rather than inferring stability from an unchanged aggregate count. On the same 256 futures, BPS 100 meets the core funded target in 178 baseline cases, 168 under face valuation, and 168 under the market-value capacity limit. The combined revision meets it in 223 baseline cases, 219 under face valuation, and 221 under the capacity limit. The policy advantage therefore persists in these tested alternatives, while the absolute feasible region remains model-dependent.')
 floor=sens[(sens.horizon==str(CORE))&(sens.outcome=='funded')&(sens.variant.str.startswith('execution_floor'))]
 changed=int((floor.gains+floor.losses).sum())
 para(f'Changing the common execution floor produces {changed} funded classification switches across the ten five-year paired floor comparisons on 256 futures each. This check separates the numerical near-zero-price boundary from the substantive access and repayment mechanisms. The market-value capacity and valuation sensitivities should be read as alternative model structures, not as sampling uncertainty around one calibrated forecast.')
 para('Ninety-six fresh boundary cases perturb observed profiles near discovered cutoffs. Twelve additional cases combine an 80% shock, a three-year closure, low capacity, high preferred costs, operating cash outflows and adverse valuation. None of the ten policies meets the funded target in those severe cases at five years. The sales-permitting revision completes payments in four, but all four still breach reserves. The historical price-shape checks likewise remain descriptive: the combined revision completes all 26 five-year payment schedules and meets the reserve condition in 24, while preserving Bitcoin per share in none.')
 head('Interpretation and contribution to the paper')
 para('The most defensible contribution is the joint effect of horizon, cash timing and capital-allocation rules. An issuance screen can look attractive when evaluated through a near-term endpoint yet leave the company exposed to later principal concentrations and continuing preferred service. Cash protection has little effect when it cannot create the required liquidity. Advance funding improves the feasible region by moving capital raising to dates when access is still available, while explicit sale authority separates inability to pay from an allocation restriction.')
 para('This supports an RDM extension with a focused substantive argument. The main figures should establish the horizon effect, compare paired policy gains and losses, and show whether revised policies and vulnerability regions transfer. PRIM should support the interpretation, with its incomplete funding coverage and lower precision stated plainly. A methodological novelty claim is unnecessary; the useful result lies in what the structured stress experiment reveals about financing choices.')
 para('The analysis does not select one universally preferred policy. More cash and earlier common issuance can sacrifice exposure to favorable Bitcoin paths and increase dilution. General-purpose Bitcoin sales can preserve payments while eroding the asset-per-share objective. The relative value of those outcomes depends on the decision criterion. The existing preferred structure and conditional cash-declaration assumption make Bitcoin-per-share preservation exceptionally demanding in this design.')
 head('Limits and reproducibility')
 para('The results remain conditional on cash repayment of convertible notes, continued cash declaration of preferred distributions, the specified authorization and capacity rules, and the original opening approximations. Conversion, refinancing, redemption, preferred deferral, restructuring, a new debt issue, or a different market-pricing relationship could alter the results. Fixed-capacity placements can be generous in distress, which is why the market-value capacity sensitivity matters. A failure to meet this modeled schedule is not a legal-default finding or a forecast of Strategy’s conduct.')
 para('Uncertainty ranges and dependence structures are exploratory choices. Main and reserved futures share a modeling framework, and complete historical price episodes overlap the block data. PRIM cutoffs are sample-dependent summaries rather than structural constants. The internal holdout keeps every policy for a given future together; the reserved source-period and generator changes test a different form of transfer. Neither warrants a probability interpretation.')
 para(f'The completed package contains {inv["total_evaluations"]:,} policy–future–variant evaluations, including the full closure continuations. Every run reconciles all atomic ledger prefixes. Twelve original configurations reproduce their retained result hashes, while the derivative engine reproduces the corresponding economic states within declared numerical tolerances. Additional checks cover principal conservation, coupon stopping, calendars, record-date entitlements, T+1 receipts, intervening-day accrual, inventory exhaustion and decisions that cannot depend on future market information. The revised rules also pass horizon and closure-prefix checks.')
 para('The source model remains at commit ea7aef9f566af346a133712b93357c5b0a0c3c33. The companion research package contains input futures, code, exact policy definitions, source provenance, complete outcome tables, PRIM trajectories and rules, validation records, figures and a replay command for full ledgers. The adaptation lock records the discovery and reserved-input hashes. The original manuscript and repository remain separate from this extension.')
 para('Release 1.1.0 adds enforced experiment fingerprints, checkpoint checksums, source dependency verification and a consolidated verification command. Opening Bitcoin price, valuation and exchange rates now derive from the corporate configuration; the normalization of the source’s Bitcoin quote preserves the original scenario paths. The checks reproduce retained economic outcomes and reject changed or damaged restart data. The package records the clean installation and report reconstruction checks and includes a GitHub workflow for automatic verification when installed in a repository.')
